class Solution {
    public List<String> getLongestSubsequence(String[] words,int[] groups){
        List<String> answer=new ArrayList<>();
        answer.add(words[0]);
        int lastGroup=groups[0];
        for(int i=1;i<words.length;i++)if(groups[i]!=lastGroup){
            answer.add(words[i]);
            lastGroup=groups[i];
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getLongestSubsequence(words:Array<String>,groups:IntArray):List<String>{
        val answer=mutableListOf(words[0]);
        var lastGroup=groups[0];
        for(i in 1 until words.size)if(groups[i]!=lastGroup){
            answer.add(words[i]);
            lastGroup=groups[i]
        };
        return answer
    }
}

